questionvariables.text:
/* River pollution: factors, all concentrations in mg/L */
n:24;
group_id:append(makelist(1,k,1,8),makelist(2,k,1,8),makelist(3,k,1,8));
group_names:["Forest","Agricultural","Industrial"];
land_use:makelist(group_names[group_id[k]],k,1,n);

/* Distances are irregular and unrelated to group assignment. */
distance_pool:makelist((15*k+rand(7)-3)/10,k,1,n);
distances:random_permutation(distance_pool);

forest_base:(18+rand(9))/10;
agricultural_base:(48+rand(13))/10;
industrial_base:(90+rand(21))/10;
clean_conc:makelist(
 if group_id[k]=1 then (round(10*forest_base)+rand(13)-6)/10
 else if group_id[k]=2 then (round(10*agricultural_base)+rand(21)-10)/10
 else (round(10*industrial_base)+rand(31)-15)/10,
 k,1,n
);
forest_clean:makelist(clean_conc[k],k,1,8);
agricultural_clean:makelist(clean_conc[k],k,9,16);
industrial_clean:makelist(clean_conc[k],k,17,24);

ta_mean_forest:float(round(100*sum(forest_clean[k],k,1,8)/8)/100);
ta_mean_agricultural:float(round(100*sum(agricultural_clean[k],k,1,8)/8)/100);
ta_mean_industrial:float(round(100*sum(industrial_clean[k],k,1,8)/8)/100);

/* Randomise rows without separating observations from their labels. */
row_order:random_permutation(makelist(k,k,1,n));
sites:makelist(sconcat("S",row_order[k]),k,1,n);

lab:["Site","Distance_km","Land_use","Concentration_mg_L"];

data:makelist(
 [
  sites[k],
  float(distances[row_order[k]]),
  land_use[row_order[k]],
  float(clean_conc[row_order[k]])
 ],
 k,1,n
);
ta_factor:[
 [1,false,"Distance_km"],
 [2,true,"Land_use"],
 [3,false,"Concentration"],
 [4,false,"Site"]
];
ta_graph:[
 [1,false,"Scatterplot of distance against concentration"],
 [2,false,"Histogram of all concentrations"],
 [3,true,"Side-by-side boxplots of concentration by land use"],
 [4,false,"Line graph connecting the three land-use categories"]
];
ta_levels:3;
/* Diagnostic means: pooling groups or dividing by all 24 sites */
overall_mean:float(round(100*sum(clean_conc[k],k,1,n)/n)/100);
forest_div24:float(round(100*sum(forest_clean[k],k,1,8)/24)/100);
agricultural_div24:float(round(100*sum(agricultural_clean[k],k,1,8)/24)/100);
industrial_div24:float(round(100*sum(industrial_clean[k],k,1,8)/24)/100);
ta_structure:[
 [1,true,"24 observations, four variables and three levels of Land_use"],
 [2,false,"Three observations, one for each land-use category"],
 [3,false,"Eight observations and 24 levels of Land_use"],
 [4,false,"24 variables and three observations"]
];


/* Diagnostic sums */
forest_sum:float(sum(forest_clean[k],k,1,8));
agricultural_sum:float(sum(agricultural_clean[k],k,1,8));
industrial_sum:float(sum(industrial_clean[k],k,1,8));

/* Sum of all 24 observations */
overall_sum:float(sum(clean_conc[k],k,1,n));

/* Means rounded to two decimal places */
mean_forest:ta_mean_forest;
mean_agricultural:ta_mean_agricultural;
mean_industrial:ta_mean_industrial;
